        pts.append(
            (
                bx + math.sin(t * 6 + i) * 0.03 * t,
                by + math.cos(t * 5 + i) * 0.025 * t,
                base_z + t * (0.34 if i < 2 else 0.28),
            )
        )
    tube(f"Steam_{i}", pts, 0.018, 0.004, M["steam"], bevel_res=2, samples=2)

