import bpy
names = ['HeroBowl','HeroBroth','NoodleLift','Egg','Yolk','Chop_0','Steam_3','NoodleA']
out = []
for n in names:
    o = bpy.data.objects.get(n)
    if not o:
        out.append({'name': n, 'missing': True})
        continue
    out.append({'name': n, 'loc': [round(v,3) for v in o.location], 'dim': [round(v,3) for v in o.dimensions]})
result = {'objs': out}

